INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_EARLY_MODERN_OCCULT','Early-Modern Western Esoteric / Grimoire Era',1450,1900)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_LEMEGETON','primary text','The Lesser Key of Solomon (Lemegeton), Book I: Ars Goetia; ed. S. L. MacGregor Mathers & Aleister Crowley (1904)','Goetic/Solomonic'),
 ('SRC_WEYER_PSEUDOMONARCHIA','primary text','Johann Weyer, Pseudomonarchia Daemonum (appendix to De praestigiis daemonum, 1577)','Goetic/Solomonic'),
 ('SRC_DEPLANCY_INFERNAL','secondary scholarship','J. A. S. Collin de Plancy, Dictionnaire Infernal (1818; 6th ed. 1863)','Goetic/Solomonic')
INSERT INTO _e VALUES
 ('ENT_GOE_ARS_GOETIA','The Seventy-Two Spirits of the Ars Goetia','Collective','Demonological classification','goetia; the 72 spirits; evocation; the Lesser Key of Solomon','A','The 72 demons catalogued in Johann Weyer''s Pseudomonarchia Daemonum (1577) and the Ars Goetia of the Lesser Key of Solomon (Lemegeton, 17th c.), ranked as kings, dukes, princes, marquises, presidents, earls and knights, each commanding legions of spirits.'),
 ('ENT_GOE_INFERNAL_HIERARCHY','The Infernal Hierarchy (Princes of Hell)','Collective','Demonological classification','hell; infernal monarchy; princes of darkness','B','The organizing rank-structure of Hell''s princes and officers systematized in the early-modern demonological treatises (Weyer 1577; Michaelis 1613; Collin de Plancy, Dictionnaire Infernal 1818) — the court standing above the 72 spirits of the Ars Goetia.'),
 ('ENT_GOE_SEVEN_DEADLY_DEMONS','The Seven Demons of the Deadly Sins (Binsfeld)','Collective','Demonological classification','seven deadly sins; pride; greed; lust; envy; gluttony; wrath; sloth','B','Peter Binsfeld''s 1589 pairing of each cardinal sin with a presiding demon: Lucifer=pride, Mammon=greed, Asmodeus=lust, Leviathan=envy, Beelzebub=gluttony, Satan=wrath, Belphegor=sloth.'),
 ('ENT_GOE_BELPHEGOR','Belphegor','Infernal prince','Infernal prince','sloth; ingenious inventions; wealth through invention; seduction','B','The deadly-sin demon of SLOTH (Binsfeld 1589); in de Plancy a prince who tempts men with ingenious inventions and the promise of ease and riches. Derived from the Moabite/Midianite Baal-Peor (Numbers 25).'),
 ('ENT_GOE_ADRAMELECH','Adramelech','Arch-demon','Infernal officer','chancellery; infernal council; the king''s wardrobe; deception','B','Great Chancellor of Hell and President of the High Council of Devils, superintendent of the demon-king''s wardrobe (de Plancy). Originally a deity of Sepharvaim to whom children were burned (2 Kings 17:31).'),
 ('ENT_GOE_BAEL','Bael','Goetic King','Goetic demon','invisibility; hidden knowledge; cunning','A','The 1st spirit, a King ruling in the East commanding 66 legions; appears with three heads (toad, man, cat) and makes the conjurer invisible.'),
 ('ENT_GOE_AGARES','Agares','Goetic Duke','Goetic demon','languages; runaways; earthquakes; nobility','A','The 2nd spirit, a Duke of the East riding a crocodile, 31 legions; teaches all languages, brings back runaways, causes earthquakes.'),
 ('ENT_GOE_VASSAGO','Vassago','Goetic Prince','Goetic demon','prophecy; finding lost or hidden things','A','The 3rd spirit, a good-natured Prince, 26 legions; declares things past and to come and discovers what is hidden or lost.'),
 ('ENT_GOE_SAMIGINA','Samigina (Gamigin)','Goetic Marquis','Goetic demon','liberal sciences; souls of the dead','A','The 4th spirit, a Marquis as a small horse or ass, 30 legions; teaches the liberal sciences and gives account of the souls of those who died in sin.'),
 ('ENT_GOE_MARBAS','Marbas','Goetic President','Goetic demon','disease and healing; mechanical arts; transformation; secrets','A','The 5th spirit, a President as a great lion, 36 legions; answers of hidden things, causes and cures diseases, teaches mechanical arts, and changes men into other shapes.'),
 ('ENT_GOE_VALEFOR','Valefor','Goetic Duke','Goetic demon','theft; familiars','A','The 6th spirit, a Duke as a lion with an ass''s head, 10 legions; a good familiar who tempts those he serves toward thievery.'),
 ('ENT_GOE_AMON','Amon','Goetic Marquis','Goetic demon','prophecy; reconciliation of feuds; procuring love','A','The 7th spirit, a Marquis as a wolf with a serpent''s tail (or raven-headed man), 40 legions; tells things past and to come, procures love, reconciles enemies. Name possibly echoes Egyptian Amun or Baal-Hammon (debated).'),
 ('ENT_GOE_BARBATOS','Barbatos','Goetic Duke','Goetic demon','speech of animals; finding treasure; reconciliation; prophecy','A','The 8th spirit, a Duke, 30 legions; gives understanding of the voices of animals, discovers treasures hidden by enchantment, tells things past and to come.'),
 ('ENT_GOE_PAIMON','Paimon','Goetic King','Goetic demon','arts and sciences; hidden knowledge; binding the will; familiars','A','The 9th spirit, a great King obedient to Lucifer riding a camel, 200 legions; teaches all arts, sciences and secret things and binds men to the conjurer''s will.'),
 ('ENT_GOE_BUER','Buer','Goetic President','Goetic demon','philosophy and logic; herbal medicine; familiars','A','The 10th spirit, a President (wheel-form, Sagittarius), 50 legions; teaches philosophy, logic and the virtues of herbs, and heals all distempers.'),
 ('ENT_GOE_GUSION','Gusion','Goetic Duke','Goetic demon','prophecy; reconciliation; honour and dignity','A','The 11th spirit, a Duke (baboon-like), 40 legions; answers things past, present and to come, reconciles friends, gives honour and dignity.'),
 ('ENT_GOE_SITRI','Sitri','Goetic Prince','Goetic demon','love and lust; revealing secrets of women','A','The 12th spirit, a Prince with leopard''s head and griffin''s wings, 60 legions; inflames men and women with love and causes them to reveal themselves wantonly.'),
 ('ENT_GOE_BELETH','Beleth','Goetic King','Goetic demon','love between man and woman','A','The 13th spirit, a terrible King riding a pale horse with trumpets sounding before him, 85 legions; procures the love of any man or woman.'),
 ('ENT_GOE_LERAJE','Leraje (Leraie)','Goetic Marquis','Goetic demon','war and battles; putrefying wounds','A','The 14th spirit, a Marquis in green clad as an archer, 30 legions; causes great battles and contests and makes arrow-wounds putrefy.'),
 ('ENT_GOE_ELIGOS','Eligos','Goetic Duke','Goetic demon','prophecy of war; discovering hidden things; favour of lords','A','The 15th spirit, a Duke as a goodly knight with lance and serpent, 60 legions; discovers hidden things, knows things to come and of wars, procures the favour of lords and knights.'),
 ('ENT_GOE_ZEPAR','Zepar','Goetic Duke','Goetic demon','love; making women barren','A','The 16th spirit, a Duke in red apparel and armour, 26 legions; makes women love men and brings them together, and can make women barren.'),
 ('ENT_GOE_BOTIS','Botis','Goetic President and Earl','Goetic demon','prophecy; reconciliation of friends and foes','A','The 17th spirit, a President and Earl (viper then man with sword), 60 legions; tells things past and to come and reconciles friends and foes.'),
 ('ENT_GOE_BATHIN','Bathin','Goetic Duke','Goetic demon','virtues of herbs and stones; transportation','A','The 18th spirit, a Duke with serpent''s tail on a pale horse, 30 legions; knows the virtues of herbs and stones and transports men suddenly between countries.'),
 ('ENT_GOE_SALLOS','Sallos','Goetic Duke','Goetic demon','love between man and woman','A','The 19th spirit, a peaceable Duke riding a crocodile with a ducal crown, 30 legions; causes men and women to love one another.'),
 ('ENT_GOE_PURSON','Purson','Goetic King','Goetic demon','hidden knowledge; finding treasure; prophecy; familiars','A','The 20th spirit, a great King riding a bear with a trumpet, 22 legions; tells things hidden, past, present and to come, discovers treasure, gives good familiars.'),
 ('ENT_GOE_MARAX','Marax (Morax)','Goetic Earl and President','Goetic demon','astronomy and liberal sciences; virtues of herbs and stones; familiars','A','The 21st spirit, an Earl and President as a bull with a man''s face, 30 legions; teaches astronomy and the liberal sciences and the virtues of herbs and stones, gives good familiars.'),
 ('ENT_GOE_IPOS','Ipos','Goetic Earl and Prince','Goetic demon','prophecy; making men witty and bold','A','The 22nd spirit, an Earl and Prince (angel with lion''s head, goose''s feet, hare''s tail), 36 legions; knows things past and to come and makes men witty and bold.'),
 ('ENT_GOE_AIM','Aim (Aym / Haborym)','Goetic Duke','Goetic demon','destruction by fire; cunning; prophecy','A','The 23rd spirit, a Duke with three heads bearing a firebrand, 26 legions; sets cities and great places ablaze, makes men witty, answers truly of private matters.'),
 ('ENT_GOE_NABERIUS','Naberius','Goetic Marquis','Goetic demon','rhetoric and the arts; restoring lost dignities','A','The 24th spirit, a Marquis as a black crane, 19 legions; makes men cunning in all arts and sciences, especially rhetoric, and restores lost dignities and honours.'),
 ('ENT_GOE_GLASYA_LABOLAS','Glasya-Labolas','Goetic President and Earl','Goetic demon','arts and sciences; bloodshed and manslaughter; prophecy; love; invisibility','A','The 25th spirit, a President and Earl as a winged dog, 36 legions; teaches all sciences in an instant, is captain of manslaughter and bloodshed, causes love and grants invisibility.'),
 ('ENT_GOE_BUNE','Bune','Goetic Duke','Goetic demon','the dead and graves; riches; wisdom and eloquence; prophecy','A','The 26th spirit, a Duke as a three-headed dragon, 30 legions; changes the place of the dead, makes men rich, wise and eloquent, gives true answers.'),
 ('ENT_GOE_RONOVE','Ronove','Goetic Marquis and Earl','Goetic demon','rhetoric and languages; favour of friends and foes; servants','A','The 27th spirit, a Marquis and Earl, 19 legions; teaches rhetoric and the knowledge of tongues, gives good servants and the favour of friends and foes.'),
 ('ENT_GOE_BERITH','Berith','Goetic Duke','Goetic demon','prophecy; turning metals to gold; dignities; deception','A','The 28th spirit, a Duke (Beal/Bolfry) as a red soldier on a red horse, 26 legions; gives true answers of past/present/future and turns metals to gold, but is a notorious liar. Also reckoned an officer of Hell''s court (Baalberith, keeper of the infernal archives) and derived from the Canaanite Baal-Berith (''lord of the covenant'').'),
 ('ENT_GOE_ASTAROTH','Astaroth','Goetic Duke','Goetic demon','prophecy; forbidden knowledge; the fall of the spirits; treasures','A','The 29th spirit, a mighty Duke as a foul angel on an infernal dragon, 40 legions; gives true answers of past/present/future, discovers all secrets, teaches the liberal sciences and discourses on the fall of the angels. Also a Grand Duke / Great Prince of Hell (Weyer, de Plancy). A demonized, re-gendered reception of the Canaanite goddess Astarte/Ashtoreth.'),
 ('ENT_GOE_FORNEUS','Forneus','Goetic Marquis','Goetic demon','rhetoric and languages; good name; love of friends and foes','A','The 30th spirit, a Marquis as a great sea-monster, 29 legions; teaches rhetoric and languages, gives men a good name, and causes them to be loved by friends and foes.'),
 ('ENT_GOE_FORAS','Foras','Goetic President','Goetic demon','virtues of herbs and stones; logic and ethics; finding lost things and treasure; invisibility','A','The 31st spirit, a President as a strong man, 29 legions; teaches the virtues of herbs and stones, logic and ethics, finds lost things and treasure, makes men invisible, witty and long-lived.'),
 ('ENT_GOE_ASMODAY','Asmoday','Goetic King','Goetic demon','arithmetic, astronomy, geometry, handicrafts; the ring of virtues; treasure; invisibility','A','The 32nd spirit, a great King with three heads on an infernal dragon, 72 legions; gives the ring of virtues, teaches arithmetic, astronomy, geometry and all handicrafts, and guards hidden treasure. The Goetic reception of Asmodeus (Book of Tobit), ultimately the Avestan Aeshma Daeva.'),
 ('ENT_GOE_GAAP','Gaap','Goetic King and President','Goetic demon','philosophy and liberal sciences; love or hatred; swift transport; familiars; the books of Amaymon','A','The 33rd spirit, a President and King under Amaymon of the south, 66 legions; teaches philosophy and the liberal sciences, causes love or hatred, carries men swiftly between kingdoms, delivers familiars.'),
 ('ENT_GOE_FURFUR','Furfur','Goetic Earl','Goetic demon','love; thunder, lightning and storms; revelation of divine things','A','The 34th spirit, an Earl as a winged hart, 26 legions; causes love between man and wife, raises tempests and lightning, and gives true answers of secret and divine things when within a triangle.'),
 ('ENT_GOE_MARCHOSIAS','Marchosias','Goetic Marquis','Goetic demon','war; true answers; faithfulness in battle','A','The 35th spirit, a Marquis as a wolf with griffin''s wings and serpent''s tail, 30 legions; a strong fighter who gives true answers, hoping to return to the Seventh Throne.'),
 ('ENT_GOE_STOLAS','Stolas','Goetic Prince','Goetic demon','astronomy; virtues of herbs and precious stones','A','The 36th spirit, a Prince as a crowned night-raven/owl, 26 legions; teaches astronomy and the virtues of herbs and precious stones.'),
 ('ENT_GOE_PHENEX','Phenex','Goetic Marquis','Goetic demon','poetry; the sciences; sweet song','A','The 37th spirit, a Marquis as a phoenix singing sweetly, 20 legions; an excellent poet who answers truly of the sciences, hoping to return to the Seventh Throne after 1,200 years.'),
 ('ENT_GOE_HALPHAS','Halphas','Goetic Earl','Goetic demon','war; building towers full of weapons; sending men of war','A','The 38th spirit, an Earl as a stock-dove, 26 legions; builds towers full of weapons and ammunition and sends men of war to appointed places.'),
 ('ENT_GOE_MALPHAS','Malphas','Goetic President','Goetic demon','building houses and towers; destroying enemies'' works; familiars; deception','A','The 39th spirit, a President as a crow then a man, 40 legions; builds houses and towers, throws down enemies'' buildings, reveals their thoughts, gives good familiars, but deceives those who sacrifice to him.'),
 ('ENT_GOE_RAUM','Raum','Goetic Earl','Goetic demon','stealing treasure; destroying cities; prophecy; love','A','The 40th spirit, an Earl as a crow then a man, 30 legions; steals treasure from kings'' houses, destroys cities and dignities, tells things past and future, reconciles friends and foes.'),
 ('ENT_GOE_FOCALOR','Focalor','Goetic Duke','Goetic demon','drowning men; overthrowing warships; wind and sea','A','The 41st spirit, a Duke as a winged man, 30 legions; drowns men and overturns warships, having power over wind and sea, hoping to return to the Seventh Throne after 1,000 years.'),
 ('ENT_GOE_VEPAR','Vepar','Goetic Duke','Goetic demon','the waters and warships; storms; death by putrefying wounds','A','The 42nd spirit, a Duke as a mermaid, 29 legions; governs the waters and guides warships, raises storms, and can kill men in three days by putrefying their wounds with worms.'),
 ('ENT_GOE_SABNOCK','Sabnock','Goetic Marquis','Goetic demon','building towers and arming them; afflicting wounds; familiars','A','The 43rd spirit, a Marquis as an armed lion-headed soldier on a pale horse, 50 legions; builds towers and castles full of weapons, afflicts men with putrefying wounds, gives good familiars.'),
 ('ENT_GOE_SHAX','Shax','Goetic Marquis','Goetic demon','taking sight/hearing/understanding; stealing; discovering hidden things; familiars','A','The 44th spirit, a Marquis as a stock-dove, 30 legions; takes away sight, hearing and understanding, steals money and horses, reveals hidden things, but deceives unless bound in a triangle.'),
 ('ENT_GOE_VINE','Vine','Goetic King and Earl','Goetic demon','discovering witches and hidden things; prophecy; building towers and casting down walls; storms','A','The 45th spirit, a King and Earl as a lion on a black horse bearing a viper, 36 legions; reveals hidden things and witches, tells past and future, builds towers, casts down walls, stirs storms.'),
 ('ENT_GOE_BIFRONS','Bifrons','Goetic Earl','Goetic demon','astrology and geometry; virtues of herbs, stones and woods; the dead','A','The 46th spirit, an Earl, 26 legions; teaches astrology, geometry and the arts and the virtues of herbs and stones, and moves bodies from grave to grave lighting seeming candles upon them.'),
 ('ENT_GOE_VUAL','Vual','Goetic Duke','Goetic demon','love of women; prophecy; reconciliation','A','The 47th spirit, a Duke as a dromedary then a man speaking Egyptian, 37 legions; procures the love of women, reconciles friends and foes, tells things past, present and future.'),
 ('ENT_GOE_HAAGENTI','Haagenti','Goetic President','Goetic demon','wisdom; transmuting metals to gold; turning wine and water','A','The 48th spirit, a President as a winged bull then a man, 33 legions; makes men wise in all things, transmutes metals into gold, and changes wine into water and water into wine.'),
 ('ENT_GOE_CROCELL','Crocell','Goetic Duke','Goetic demon','geometry and the liberal sciences; hidden things; warming waters','A','The 49th spirit, a Duke, 48 legions; teaches geometry and the liberal sciences, discourses of hidden things, and warms waters producing the appearance of baths.'),
 ('ENT_GOE_FURCAS','Furcas','Goetic Knight','Goetic demon','philosophy, astronomy, rhetoric, logic; chiromancy and pyromancy','A','The 50th spirit, a Knight, 20 legions; teaches philosophy, astronomy, rhetoric, logic, chiromancy and pyromancy.'),
 ('ENT_GOE_BALAM','Balam','Goetic King','Goetic demon','prophecy; invisibility; wit','A','The 51st spirit, a terrible King, 40 legions; answers truly of things past, present and to come, gives invisibility and makes men witty.'),
 ('ENT_GOE_ALLOCES','Alloces','Goetic Duke','Goetic demon','astronomy and the liberal sciences; familiars','A','The 52nd spirit, a Duke, 36 legions; teaches astronomy and the liberal sciences and bestows good and faithful familiars.'),
 ('ENT_GOE_CAIM','Caim','Goetic President','Goetic demon','the voices of birds and animals; prophecy; disputation','A','The 53rd spirit, a President, 30 legions; gives understanding of the voices of birds, oxen, dogs and the sound of waters, and answers truly of things to come.'),
 ('ENT_GOE_MURMUR','Murmur','Goetic Duke and Earl','Goetic demon','the dead; philosophy; necromancy','A','The 54th spirit, a Duke and Earl, 30 legions; teaches philosophy and constrains the souls of the deceased to appear and answer questions.'),
 ('ENT_GOE_OROBAS','Orobas','Goetic Prince','Goetic demon','prophecy; dignities and favour; protection from deceiving spirits','A','The 55th spirit, a Prince, 20 legions; answers truly of past/present/future and of divinity and creation, gives dignities and favour, and is faithful, not suffering the conjurer to be tempted by any spirit.'),
 ('ENT_GOE_GREMORY','Gremory','Goetic Duke','Goetic demon','love of women; hidden treasure; prophecy','A','The 56th spirit, a Duke, 26 legions; tells of things past/present/future and of hidden treasures, and procures the love of women young and old.'),
 ('ENT_GOE_OSE','Ose','Goetic President','Goetic demon','the liberal sciences; transformation; delusion','A','The 57th spirit, a President, 30 legions; makes one cunning in the liberal sciences, gives true answers of secret things, and can transform a man into any shape or drive him to madness.'),
 ('ENT_GOE_AMY','Amy','Goetic President','Goetic demon','astrology and the liberal sciences; hidden treasure; familiars','A','The 58th spirit, a President, 36 legions; teaches astrology and the liberal sciences, gives good familiars, and reveals treasures kept by spirits.'),
 ('ENT_GOE_ORIAS','Orias','Goetic Marquis','Goetic demon','astrology and the stars; dignities; transformation','A','The 59th spirit, a Marquis, 30 legions; teaches the virtues of the stars and the mansions of the planets, gives dignities and the favour of friends and foes, and transforms men.'),
 ('ENT_GOE_VAPULA','Vapula','Goetic Duke','Goetic demon','handicrafts, professions, philosophy and sciences','A','The 60th spirit, a Duke, 36 legions; makes men knowing in handicrafts, professions, philosophy and other sciences.'),
 ('ENT_GOE_ZAGAN','Zagan','Goetic King and President','Goetic demon','transmutation of liquids and metals; wit','A','The 61st spirit, a King and President, 33 legions; makes men witty, turns wine to water and water to wine, blood to wine and metal to coin, and makes fools wise.'),
 ('ENT_GOE_VOLAC','Volac','Goetic President','Goetic demon','hidden treasure; knowledge of serpents','A','The 62nd spirit, a President (Ualac/Valak), 38 legions; gives true answers of hidden treasures and reveals where serpents may be found, delivering them harmless to the magician.'),
 ('ENT_GOE_ANDRAS','Andras','Goetic Marquis','Goetic demon','war; death; sowing discord','A','The 63rd spirit, a Marquis, 30 legions; sows discord and will slay the master, servants and assistants if the conjurer is not wary.'),
 ('ENT_GOE_HAURES','Haures (Flauros)','Goetic Duke','Goetic demon','prophecy and the fall of spirits; destroying enemies by fire; protection','A','The 64th spirit, a Duke (Flauros), 36 legions; answers truly of past/present/future, of divinity and the fall of spirits, destroys the conjurer''s enemies by fire and guards against other spirits.'),
 ('ENT_GOE_ANDREALPHUS','Andrealphus','Goetic Marquis','Goetic demon','geometry and astronomy; subtle reasoning; transformation into a bird','A','The 65th spirit, a Marquis, 30 legions; teaches geometry, measurement and astronomy, makes men subtle in reasoning, and can transform a man into the likeness of a bird.'),
 ('ENT_GOE_CIMEJES','Cimejes (Kimaris)','Goetic Marquis','Goetic demon','grammar, logic, rhetoric; hidden treasure; the spirits of Africa','A','The 66th spirit, a Marquis (Kimaris), 20 legions; rules the spirits of Africa, teaches grammar, logic and rhetoric, discovers lost or hidden things and buried treasure, and makes excellent warriors.'),
 ('ENT_GOE_AMDUSIAS','Amdusias','Goetic Duke','Goetic demon','music; command of trees; familiars','A','The 67th spirit, a Duke (Amdukias), 29 legions; causes unseen trumpets and musical instruments to be heard and bends trees at the conjurer''s will, giving excellent familiars.'),
 ('ENT_GOE_BELIAL','Belial (Goetia)','Goetic King','Goetic demon','dignities; favour of friends and foes; familiars','A','The 68th spirit, a mighty King created next after Lucifer, 80 legions; distributes preferments and dignities, gives the favour of friends and foes, and requires offerings to answer truly. The Goetic reception of the biblical/Second-Temple Belial.'),
 ('ENT_GOE_DECARABIA','Decarabia','Goetic Marquis','Goetic demon','virtues of birds and precious stones; command of birds','A','The 69th spirit, a Marquis, 30 legions; discovers the virtues of birds and precious stones and makes the likeness of birds fly before the conjurer as familiars.'),
 ('ENT_GOE_SEERE','Seere','Goetic Prince','Goetic demon','swift transport; abundance; discovering theft and hidden treasure','A','The 70th spirit, a Prince under Amaymon, 26 legions; good-natured, goes and returns in the twinkling of an eye, brings abundance, discovers thefts and hidden treasure.'),
 ('ENT_GOE_DANTALION','Dantalion','Goetic Duke','Goetic demon','all arts and sciences; reading and changing thoughts; love','A','The 71st spirit, a Duke, 36 legions; teaches all arts and sciences, declares the secret counsel of any person, reads and changes thoughts, and causes love, showing the likeness of any person.'),
 ('ENT_GOE_ANDROMALIUS','Andromalius','Goetic Earl','Goetic demon','punishing thieves and wickedness; recovering stolen goods; hidden treasure','A','The 72nd and last spirit, an Earl, 36 legions; brings back thieves and stolen goods, discovers wickedness and underhand dealing, punishes thieves, and reveals hidden treasures.');
INSERT INTO entities (entity_id,canonical_name,tradition,entity_type,category,primary_domains,cult_scope,evidence_confidence,review_status,inclusion_basis,earth_association_score,chthonic_flag,serpent_flag,short_note)
INSERT INTO _s VALUES
 ('ENT_GOE_ARS_GOETIA','SRC_WEYER_PSEUDOMONARCHIA','The 72 demons catalogued in Johann Weyer''s Pseudomonarchia Daemonum (1577) and the Ars Goetia of the Lesser Key of Solomon (Lemegeton, 17th c.), ranked as kings, dukes, princes, marquises, presidents, earls and knights, each commanding legions of spirits.','primary text attestation'),
