INSERT INTO _r VALUES
 ('ENT_GOE_ARS_GOETIA','member_of','ENT_GOE_INFERNAL_HIERARCHY','medium','The 72 spirits of the Ars Goetia sit beneath the princely infernal court in the demonological rank structure.',''),
